awarded_scores = {}

def pytest_runtest_makereport(item, call):
    if call.when == "call":
        outcome = call.excinfo
        test_name = item.name
        if outcome is None:
            score = TEST_GRADES.get(test_name, 0)
            awarded_scores[test_name] = score
        else:
            awarded_scores[test_name] = 0

def pytest_terminal_summary(terminalreporter, exitstatus, config):
    total_awarded = sum(awarded_scores.values())
    total_possible = sum(TEST_GRADES.values())

    terminalreporter.write_sep("=", "GRADE REPORT")
    for test_name, score in awarded_scores.items():
        total = TEST_GRADES[test_name]
        terminalreporter.write_line(f"{test_name}: {score}/{total}")
    terminalreporter.write_sep(
        "=", f"FINAL SCORE: {total_awarded}/{total_possible}")
